import { createPublicClient, http, numberToHex, type Address, type Hex, type Transport } from 'viem';
import { rpcUrlFromEnv } from '../onehive/clients/rpc-url.js';
import { fail, ok } from '../onehive/schemas.js';
import { commands } from './commands.js';
import { planCourtCommand } from './run.js';
import { CourtError, MissingRead, Snapshot, uint } from './snapshot.js';

// Only missing getter calldata generated by the planner can enter the transport.
export async function captureCourtRecording(input: unknown, height: string, transport?: Transport) {
  const parsed = commands.safeParse(input);
  const blockNumber = uint.safeParse(height);
  if (!parsed.success || !blockNumber.success) return fail('court_input', 'Supply a valid request and a decimal block height.');
  const r = parsed.data;
  const client = createPublicClient({ transport: transport ?? http(rpcUrlFromEnv(r.chainId)) });
  try {
    if (await client.getChainId() !== r.chainId) return fail('wrong_chain', 'RPC chain differs from the request.');
    const block = await client.request({ method: 'eth_getBlockByNumber', params: [numberToHex(blockNumber.data), false] });
    if (!block?.hash || block.number == null || BigInt(block.number) !== blockNumber.data || block.timestamp == null) {
      return fail('block_unavailable', 'RPC must return the requested numbered block with a hash and timestamp.');
    }
    const calls: Array<{ to: Address; data: Hex; result: Hex }> = [];
    const recording = { chainId: r.chainId, blockNumber: height, blockHash: block.hash, timestamp: BigInt(block.timestamp).toString(), calls };
    for (;;) {
      try {
        planCourtCommand(r, new Snapshot(recording));
        return ok(recording, ['Captured public getters for this request at the reported canonical block hash. RPC provenance is unverified.']);
      } catch (error) {
        if (!(error instanceof MissingRead)) throw error;
        if (calls.length >= 256) return fail('court_read_limit', 'Capture exceeded the 256-getter limit for one request.');
        const { to, data } = error.request;
        const result = await client.request({ method: 'eth_call', params: [{ to, data }, { blockHash: block.hash, requireCanonical: true }] });
        calls.push({ to, data, result });
      }
    }
  } catch (error) {
    if (error instanceof CourtError) return fail('court_precondition', error.message);
    return fail('court_capture_failed', 'Unable to capture public getters at the specified canonical block. Check the chain, height and RPC hash-read support.');
  }
}
